<?php
namespace App\Core\Connectors\Drivers;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Connectors\DTO\{ConnectorAction,ConnectorResult};use App\Models\ConnectorConnection;
final class ApolloConnector extends AbstractConnector {public function id():string{return 'apollo';}public function label():string{return 'Apollo';}public function actions():array{return [new ConnectorAction('people_search','Search net-new B2B prospects. Search results do not include email or phone unless separately enriched.',RiskLevel::Read,['type'=>'object','properties'=>['person_titles'=>['type'=>'array','items'=>['type'=>'string']],'person_locations'=>['type'=>'array','items'=>['type'=>'string']],'organization_locations'=>['type'=>'array','items'=>['type'=>'string']],'page'=>['type'=>'integer'],'per_page'=>['type'=>'integer']]]),new ConnectorAction('people_enrich','Enrich one known person through Apollo.',RiskLevel::Read,['type'=>'object','properties'=>['email'=>['type'=>'string'],'first_name'=>['type'=>'string'],'last_name'=>['type'=>'string'],'organization_name'=>['type'=>'string']]])];}public function configurationSchema():array{return ['credentials'=>['api_key'=>['type'=>'password','required'=>true]],'fields'=>[]];}private function clientFor(ConnectorConnection $c){return $this->client(['x-api-key'=>$this->bearer($c)]);}public function test(ConnectorConnection $c):bool{try{return $this->clientFor($c)->post('https://api.apollo.io/api/v1/mixed_people/api_search',['page'=>1,'per_page'=>1])->successful();}catch(\Throwable){return false;}}public function execute(ConnectorConnection $c,string $action,array $a):ConnectorResult{$this->action($action);return match($action){'people_search'=>ConnectorResult::success($this->clientFor($c)->post('https://api.apollo.io/api/v1/mixed_people/api_search',$a)->throw()->json()),'people_enrich'=>ConnectorResult::success($this->clientFor($c)->post('https://api.apollo.io/api/v1/people/match',$a)->throw()->json()),default=>ConnectorResult::failure('Unsupported action')};}}
